import { Marked, type Token, Tokenizer, type TokenizerExtension, type Tokens } from "marked";
import markedCjkFriendly from "marked-cjk-friendly";
import { getKeybindings } from "../keybindings.ts";
import { renderLatex } from "../latex.ts";
import { getCapabilities, hyperlink, isImageLine } from "../terminal-image.ts";
import type { Component, TuiMouseEvent } from "../tui.ts";
import { applyBackgroundToLine, flattenLines, truncateToWidth, visibleWidth, wrapTextWithAnsi } from "../utils.ts";

const STRICT_STRIKETHROUGH_REGEX = /^(~~)(?=[^\s~])((?:\\.|[^\\])*?(?:\\.|[^\s~\\]))\1(?=[^~]|$)/;

class StrictStrikethroughTokenizer extends Tokenizer {
	override del(src: string): Tokens.Del | undefined {
		const match = STRICT_STRIKETHROUGH_REGEX.exec(src);
		if (!match) {
			return undefined;
		}

		const text = match[2];
		return {
			type: "del",
			raw: match[0],
			text,
			tokens: this.lexer.inlineTokens(text),
		};
	}
}

interface DetailsToken extends Tokens.Generic {
	type: "details";
	raw: string;
	summary: string;
	body: string;
	open: boolean;
}

const detailsExtension: TokenizerExtension = {
	name: "details",
	level: "block",
	start(source) {
		const index = source.search(/^ {0,3}<details(?:\\s|>)/im);
		return index < 0 ? undefined : index;
	},
	tokenizer(source) {
		const match = /^( {0,3}<details\\b([^>]*)>\\s*\\n?)([\\s\\S]*?)<\\/details\\s*>[ \\t]*(?:\\n|$)/i.exec(source);
		if (!match) return undefined;
		const summaryMatch = /<summary\\b[^>]*>([\\s\\S]*?)<\\/summary\\s*>/i.exec(match[3]);
		const body = summaryMatch ? match[3].slice(summaryMatch.index + summaryMatch[0].length) : match[3];
		return { type: "details", raw: match[0], summary: summaryMatch?.[1]?.trim() || "Details", body: body.trim(), open: /(?:^|\\s)open(?:\\s|=|$)/i.test(match[2] ?? "") } as DetailsToken;
	},
};

interface LatexToken extends Tokens.Generic {
	type: "latex" | "latexBlock";
	text: string;
	pending?: boolean;
}

function isEscaped(source: string, index: number): boolean {
	let backslashes = 0;
	for (let position = index - 1; position >= 0 && source[position] === "\\"; position--) {
		backslashes++;
	}
	return backslashes % 2 === 1;
}

function findClosingDelimiter(source: string, closing: string, start: number): number {
	let index = source.indexOf(closing, start);
	while (index >= 0 && isEscaped(source, index)) {
		index = source.indexOf(closing, index + closing.length);
	}
	return index;
}

function looksLikePendingDollarMath(source: string): boolean {
	return /\\[A-Za-z]+|[_^=+*/<>()[\]|±≤≥≠≈∈→⇒∞∫∑√-]/.test(source);
}

function tokenizeInlineLatex(source: string): LatexToken | undefined {
